import pathlib,json,datetime
P=pathlib.Path(__file__).resolve().parent
t=json.load(open(P/'TORCH_RESULTS.json'));n=json.load(open(P/'NATIVE_RESULTS.json')) if (P/'NATIVE_RESULTS.json').exists() else {'pairs':0,'raw_windows':0,'rows':[]}
lines=['AICPU baseline修正与二号远端复测','更新: '+datetime.datetime.now(datetime.timezone.utc).isoformat(),'',f"已验收: torch {t['pairs']}/14，native {n['pairs']}/10；另5个算法/精度项未修复。",'本轮范围: 上轮29个严重倍率AICPU pair。新增365个torch发现仅留档，不纳入本轮修正。','远端: openlibing-DevEnv-055409，物理32 AIC / 64 AIV，CANN9.1；全程共享npu-guard，原CPU oracle/checker/seed/容差保持。',f"原始窗口重放: {t['raw_windows']+n['raw_windows']}。Torch为原/新实现各15窗口；native为修正后15窗口。所有已验收修正窗口AICPU数为0。",'每次调用前使用原1GiB flush并同步，3次预热，15次独立profile；仍采用v3 distinct task设备累计时间，无host/device口径混用。','以下倍率复算沿用已有网页TileOPs耗时，并未在本轮重测TileOPs，也未发布网站。','','Torch同轮原/新对照：','operator | case | 同轮原baseline us | 修正baseline us | 原网页倍率 -> 复算倍率']
for r in t['rows']:lines.append(f"{r['op']} | {r['case']} | {r['same_round_original_us']:.3f} | {r['fixed_us']:.3f} | {r['old_web_ratio']:.2f}x -> {r['recomputed_ratio_with_published_tileops']:.2f}x")
lines+=['','Native修正后结果（旧值来自一号远端公开记录，新值来自二号，非同轮A/B）：']
for r in n['rows']:lines.append(f"{r['op']} | {r['case']} | {r['old_web_us']:.3f} -> {r['fixed_us']:.3f} us | {r['old_web_ratio']:.2f}x -> {r['recomputed_ratio_with_published_tileops']:.2f}x")
lines+=['','修正内容：','1. INT4: 保留原FP32量化公式，仅以乘16和负低半字节加16替代int8位移/按位与。','2. 复数All/Any/CountNonzero: 用整数原始位屏蔽符号位判断非零，再调用原归约；不将complex128降为float32。','3. native MaskedFill/Where: 先按原始uint8!=0规范化BOOL，再用INT32权重求和打包BOOL掩码，原TileLang VSEL kernel不变。','4. native LogicalNot: 按原始uint8!=0规范化BOOL，先用FP32生成全1再转INT16替代触发OnesLike AICPU的常量创建；原XOR kernel不变。','全部新增转换仍在计时函数内。','','未修复项：','4个Cumprod：AICPU是前缀乘积主体，简单树形重排存在有限值变inf的反例，不能当等价替换。','1个SelectiveScan：FP64非线性路径是为了通过原checker；原FP32已出现1.42157e-5绝对误差（上限1e-5）的历史失败，不能直接降低精度。','详见 hard/DEFERRED.json 与 CUMPROD_CPU_REVIEW.json；保留旧测量，不冒充已修复。','','交付：','TORCH_RESULTS.csv / NATIVE_RESULTS.csv: pair级结果。','fixes.py / native-v4/tla_adapters_v2.py: 实际复测的修正源码。','torch-worker-routing.patch / native-adapter-v4.patch: 基于实测原源码的接入补丁；CPU oracle不改。','INTEGRATION.txt: 新source manifest/measurement identity要求；未覆盖旧记录或发布网页。','torch14-evidence.tar.gz: 420窗口完整原始证据及源码/guard。','../torch-aicpu-audit-20261108/: 本次新增发现的完整记录。']
(P/'REPORT.txt').write_text('\n'.join(lines)+'\n')
